import static bootcamp.Check.*;

import java.util.*;
import java.util.concurrent.CompletableFuture;

class Exercise {

    /** A future of every value, in input order, done when all inputs are done. */
    static CompletableFuture<List<String>> sequence(List<CompletableFuture<String>> fs) {
        throw new UnsupportedOperationException("TODO: wait for all, then join each in list order");
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("completed futures sequence in input order", () ->
            eq(sequence(List.of(CompletableFuture.completedFuture("a"), CompletableFuture.completedFuture("b"), CompletableFuture.completedFuture("c"))).join(),
                List.of("a", "b", "c")));
        test("no futures make an already-completed empty list (boundary)", () -> {
            var result = sequence(List.of());
            ok(result.isDone(), "nothing to wait for");
            eq(result.join(), List.of());
        });
        test("the result waits for the last input", () -> {
            var late = new CompletableFuture<String>();
            var result = sequence(List.of(CompletableFuture.completedFuture("a"), late));
            ok(!result.isDone(), "one input is still pending");
            late.complete("b");
            ok(result.isDone(), "completing the input completes the sequence");
            eq(result.join(), List.of("a", "b"));
        });
        test("input order wins over completion order", () -> {
            var first = new CompletableFuture<String>();
            var second = new CompletableFuture<String>();
            var result = sequence(List.of(first, second));
            second.complete("2");
            first.complete("1");
            eq(result.join(), List.of("1", "2"));
        });
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

