class Exercise {

    /** The primary's value, or — only when it failed — the backup's (counting each ask). */
    static CompletableFuture<String> withBackup(CompletableFuture<String> primary, Supplier<CompletableFuture<String>> backup, AtomicInteger asked) {
        throw new UnsupportedOperationException("TODO: compose on the error path only, creating the backup there");
