    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a healthy primary answers", () ->
            eq(withBackup(CompletableFuture.completedFuture("primary-row"), () -> CompletableFuture.completedFuture("replica-row"), new AtomicInteger()).join(),
